import os
import boto3
import json
from typing import Any, Dict, List

def extract_tables(payload, config=None):
    config = config or {}
    client = boto3.client("textract", region_name=config.get("region_name") or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))
    result = client.analyze_document(
        Document={"Bytes": payload},
        FeatureTypes=["TABLES"],
    )

    blocks = result.get("Blocks", [])
    blocks_by_id = {b.get("Id"): b for b in blocks if b.get("Id")}

    def get_text(block: Dict[str, Any]) -> str:
        text_parts = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for cid in rel.get("Ids", []) or []:
                    child = blocks_by_id.get(cid)
                    if child and child.get("BlockType") == "WORD":
                        text_parts.append(child.get("Text", ""))
                    elif child and child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                        text_parts.append("X")
        return " ".join(t for t in text_parts if t)

    tables = []
    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue
        table = {"id": block.get("Id"), "rows": []}
        cells = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for cid in rel.get("Ids", []) or []:
                    child = blocks_by_id.get(cid)
                    if child and child.get("BlockType") == "CELL":
                        cells.append(child)

        by_row = {}
        for cell in cells:
            row_index = cell.get("RowIndex", 0) or 0
            col_index = cell.get("ColumnIndex", 0) or 0
            by_row.setdefault(row_index, {})[col_index] = {
                "text": get_text(cell),
                "row_span": cell.get("RowSpan", 1),
                "col_span": cell.get("ColumnSpan", 1),
                "confidence": cell.get("Confidence"),
            }

        for row_index in sorted(by_row):
            row_cells = by_row[row_index]
            max_col = max(row_cells) if row_cells else 0
            row = []
            for col_index in range(1, max_col + 1):
                row.append(row_cells.get(col_index, {"text": "", "row_span": 1, "col_span": 1, "confidence": None}))
            table["rows"].append(row)
        tables.append(table)

    result = {"tables": tables, "raw": result}
    return result
